pub async fn repository_recover_claim(
    State(state): State<AppState>,
    Path((repository_id, task_id)): Path<(String, String)>,
    Json(request): Json<RecoverClaimRequest>,
) -> Result<Json<RecoverClaimResponse>, StatusCode> {
    // Same enrolment-first check every other Bridge route already follows:
    // a repository outside the caller's tenant reads exactly like one that
    // was never enrolled.
    match state
        .fleet
        .repository(&state.tenant_id, &repository_id)
        .await
    {
        Ok(Some(_)) => {}
        Ok(None) => return Err(StatusCode::NOT_FOUND),
        Err(error) => {
            tracing::error!(%error, "Bridge repository lookup before claim recovery failed");
            return Err(StatusCode::INTERNAL_SERVER_ERROR);
        }
    }

    // The caller names who should hold the claim next, not who holds it now -
    // the handler derives that itself, the same way a human today reads
    // `owner` off Lodestar's own overlap view before deciding to recover.
    let current = match state
        .fleet
        .claim_owner(&state.tenant_id, &repository_id, &task_id)
        .await
    {
        Ok(Some(claim)) => claim,
        Ok(None) => return Err(StatusCode::NOT_FOUND),
        Err(error) => {
            tracing::error!(%error, "Bridge claim-owner lookup before recovery failed");
            return Err(StatusCode::INTERNAL_SERVER_ERROR);
        }
    };

    let recover_request = ClaimRecoverRequest {
        tenant_id: state.tenant_id.to_string(),
        repository_id,
        task_id,
        expected_owner: current.owner_id,
        owner_id: request.owner_id,
        reason: request.reason,
        branch: request.branch,
        lease: Duration::from_secs(request.lease_seconds),
        paths: current.paths,
        symbols: current.symbols,
    };

    let claims = &state.claims;
    match claims.recover(&recover_request, SystemTime::now()).await {
        Ok(result) if result.outcome == ClaimLeaseOutcome::Granted => {
            Ok(Json(RecoverClaimResponse {
                task_id: recover_request.task_id,
                owner_id: result.owner_id,
                branch: result.branch,
                claim_started_at_seconds: unix_seconds(result.claim_started_at),
                lease_expires_at_seconds: unix_seconds(result.lease_expires_at),
                claim_lapses: result.claim_lapses,
            }))
        }
        // Rejected means the owner changed concurrently or the lease is
        // still live - ClaimStore::recover's own unconditional expiry check
        // (ADR-0111), not a judgment Bridge makes itself.
        Ok(_rejected) => Err(StatusCode::CONFLICT),
        Err(ClaimStoreError::MissingReason | ClaimStoreError::InvalidLease) => {
            Err(StatusCode::BAD_REQUEST)
        }
        Err(error) => {
            tracing::error!(%error, "Bridge claim recovery failed");
            Err(StatusCode::INTERNAL_SERVER_ERROR)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn claim_cursor_requires_both_compound_key_fields() {
        for query in [
            ClaimListQuery {
                after_lease_expires_at_micros: Some(1),
                after_task_id: None,
            },
            ClaimListQuery {
                after_lease_expires_at_micros: None,
                after_task_id: Some("task:a".to_string()),
            },
            ClaimListQuery {
                after_lease_expires_at_micros: Some(1),
                after_task_id: Some(String::new()),
            },
            ClaimListQuery {
                after_lease_expires_at_micros: None,
                after_task_id: Some(String::new()),
            },
        ] {
            assert_eq!(parse_claim_cursor(query), Err(StatusCode::BAD_REQUEST));
        }
    }

    #[test]
    fn claim_cursor_round_trips_signed_epoch_microseconds() {
        let before_epoch = ClaimListQuery {
            after_lease_expires_at_micros: Some(-1),
            after_task_id: Some("task:before".to_string()),
        };
        let after_epoch = ClaimListQuery {
            after_lease_expires_at_micros: Some(1),
            after_task_id: Some("task:after".to_string()),
        };

        let before = parse_claim_cursor(before_epoch)
            .expect("before-epoch cursor parses")
            .expect("cursor exists");
        let after = parse_claim_cursor(after_epoch)
            .expect("after-epoch cursor parses")
            .expect("cursor exists");
        assert_eq!(
            (epoch_micros(before.lease_expires_at), before.task_id),
            (Some(-1), "task:before".to_string())
        );
        assert_eq!(
            (epoch_micros(after.lease_expires_at), after.task_id),
            (Some(1), "task:after".to_string())
        );
    }

    #[test]
    fn terminal_claim_page_has_no_next_cursor() {
        let response = ActiveWorkResponse::try_from(ClaimListPage {
            claims: Vec::new(),
            next_after: None,
        })
        .expect("terminal page converts to a response");

        assert_eq!(response.next_after, None);
    }

    #[test]
    fn nonterminal_claim_page_serializes_its_compound_next_cursor() {
        let response = ActiveWorkResponse::try_from(ClaimListPage {
            claims: Vec::new(),
            next_after: Some(ClaimListCursor {
                lease_expires_at: UNIX_EPOCH + Duration::from_micros(42),
                task_id: "task:next".to_string(),
            }),
        })
        .expect("nonterminal page converts to a response");

        assert_eq!(
            serde_json::to_value(response).expect("response serializes"),
            serde_json::json!({
                "claims": [],
                "next_after": {
                    "lease_expires_at_micros": 42,
                    "task_id": "task:next",
                },
            })
        );
    }
}
